import { AlertDialog } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { useState } from 'react';
function AlertDialogExample() {
  const [open, setOpen] = useState(false),
    [removed, setRemoved] = useState(false);
  return (
    <>
      <Button onClick={() => setOpen(true)} disabled={removed}>
        Remove material
      </Button>
      <AlertDialog
        open={open}
        onOpenChange={setOpen}
        title="Remove this material?"
        confirmLabel="Remove"
        destructive
        onConfirm={() => {
          setRemoved(true);
          setOpen(false);
        }}
      >
        The sample material will be removed from this session.
      </AlertDialog>
      {removed && (
        <>
          <p role="status">Material removed.</p>
          <Button onClick={() => setRemoved(false)}>Restore material</Button>
        </>
      )}
    </>
  );
}
export function Example() {
  return <AlertDialogExample />;
}
